const VOWELS: &[char] = &['a', 'e', 'i', 'o', 'u'];

pub fn translate(input: &str) -> String {
    input
        .split_whitespace()
        .map(translate_word)
        .collect::<Vec<_>>()
        .join(" ")
}

fn translate_word(word: &str) -> String {
    let mut chars = word.chars();
    let first = chars.next().unwrap_or('\0');

    // Rule 1: word begins with a vowel, or starts with "xr" or "yt".
    if VOWELS.contains(&first) || word.starts_with("xr") || word.starts_with("yt") {
        return format!("{word}ay");
    }

    // Find where the leading consonant cluster ends.
    let mut split = word.len();
    for (i, c) in word.char_indices().skip(1) {
        if VOWELS.contains(&c) {
            split = i;
            break;
        }
        // Rule 3: "qu" counts as part of the consonant cluster.
        if c == 'q' && word[i..].starts_with("qu") {
            split = i + 2;
            break;
        }
        // Rule 4: "y" acts as a vowel after one or more consonants.
        if c == 'y' {
            split = i;
            break;
        }
    }

    format!("{}{}ay", &word[split..], &word[..split])
}

